input.newString:
function setStatus(id: number, status: 'fulfilled' | 'deleted'): ListingRow | undefined {
  const db = getDb();
  const row = getListingById(id);
  if (!row) {
    return undefined;
  }

  const transitionMatrix: Record<string, ('fulfilled' | 'deleted')[] | null> = {
    active: ['fulfilled', 'deleted'],
    fulfilled: ['deleted'],
  };
  const allowed = transitionMatrix[row.status];
  if (allowed === null || !allowed.includes(status)) {
    throw new Error(
      `Cannot transition listing #${id} from status '${row.status}' to '${status}'.`,
    );
  }

  db.update(listings).set({ status, updatedAt: now() }).where(eq(listings.id, id)).run();
  return getListingById(id);
}

