describe('statusTransitionMatrix', () => {
  function seedActiveListing(): { id: number; status: 'active' } {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    return { id: listing.id, status: listing.status };
  }

  function seedFulfilledListing(): { id: number; status: 'fulfilled' } {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    fulfillListing(listing.id);
    return { id: listing.id, status: listing.status };
  }

  function seedDeletedListing(): { id: number; status: 'deleted' } {
    seedServer();
    const { listing } = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    softDeleteListing(listing.id);
    return { id: listing.id, status: listing.status };
  }

  function seedExpiredListing(): { id: number; status: 'expired' } {
    seedServer();
    const db = getDb();
    const past = Date.now() - 31 * 24 * 3600 * 1000;
    db.insert(listings)
      .values({
        ...baseInput(),
        intent: 'have',
        accepts: 'cash',
        serverId: '200',
        userId: 'u1',
        username: 'alice',
        cardName: 'Expired Card',
        cardNameNormalized: 'expired card',
        cardSet: null,
        cardImageUrl: null,
        finish: null,
        variant: null,
        collectorNumber: null,
        manapoolUrl: null,
        condition: 'nm',
        priceCents: 1000,
        quantity: 1,
        notes: null,
        status: 'active',
        expiresAt: past,
        createdAt: past,
        updatedAt: past,
      })
      .run();
    const listing = db.select().from(listings).where(eq(listings.id, db.select({ value: listings.id }).from(listings).get()?.value ?? 1)).get();
    const id = listing?.id;
    if (!id) {
      throw new Error('Failed to get expired listing id');
    }
    return { id, status: 'expired' };
  }

  it('allows active -> fulfilled transition, returns updated listing', () => {
    const { id } = seedActiveListing();
    const result = fulfillListing(id);
    expect(result?.status).toBe('fulfilled');
    expect(getListingById(id)?.status).toBe('fulfilled');
  });

  it('allows active -> deleted transition, returns updated listing', () => {
    const { id } = seedActiveListing();
    const result = softDeleteListing(id);
    expect(result?.status).toBe('deleted');
    expect(getListingById(id)?.status).toBe('deleted');
  });

  it('allows fulfilled -> deleted transition (cleanup), returns updated listing', () => {
    const { id } = seedFulfilledListing();
    const result = softDeleteListing(id);
    expect(result?.status).toBe('deleted');
    expect(getListingById(id)?.status).toBe('deleted');
  });

  it('throws when attempting to re-fulfill an already-fulfilled listing', () => {
    seedServer();
    const row = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    fulfillListing(row.listing.id);
    expect(() => fulfillListing(row.listing.id)).toThrow(/cannot transition from.*fulfilled.*fulfilled/i);
    expect(listings.query().where(eq(listings.id, row.listing.id)).as().all()).toHaveLength(1);
  });

  it('throws when attempting to re-delete an already-deleted listing', () => {
    seedServer();
    const row = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    softDeleteListing(row.listing.id);
    expect(() => softDeleteListing(row.listing.id)).toThrow(/cannot transition from.*deleted.*deleted/i);
  });

  it('throws when attempting to fulfill a deleted listing', () => {
    seedServer();
    const row = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    softDeleteListing(row.listing.id);
    expect(() => fulfillListing(row.listing.id)).toThrow(/cannot transition from.*deleted.*fulfilled/i);
  });

  it('throws when attempting to fulfill an expired listing', () => {
    seedServer();
    const row = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    const db = getDb();
    const past = Date.now() - 31 * 24 * 3600 * 1000;
    db.update(listings)
      .set({ status: 'expired', expiresAt: past })
      .where(eq(listings.id, row.listing.id))
      .run();
    expect(() => fulfillListing(row.listing.id)).toThrow(/cannot transition from.*expired/i);
  });

  it('throws when attempting to delete an expired listing', () => {
    seedServer();
    const row = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    const db = getDb();
    const past = Date.now() - 31 * 24 * 3600 * 1000;
    db.update(listings)
      .set({ status: 'expired', expiresAt: past })
      .where(eq(listings.id, row.listing.id))
      .run();
    expect(() => softDeleteListing(row.listing.id)).toThrow(/cannot transition from.*expired/i);
  });

  it('throws when attempting to fulfill an active listing multiple times', () => {
    seedServer();
    const row = createListing({ ...baseInput(), intent: 'have', accepts: 'cash' });
    fulfillListing(row.listing.id);
    expect(() => fulfillListing(row.listing.id)).toThrow(/cannot transition from.*fulfilled/i);
    const updated = getListingById(row.listing.id);
    expect(updated?.status).toBe('fulfilled');
  });
});

